content.text:
The evidence is consistent: one fault, at ts-travel-plan-service, and its effect reaches the user through ts-ui-dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS parent_svc, p.span_name AS parent_span, p.attr_span_kind AS parent_kind, p.attr_http_request_method AS parent_method, c.service_name AS child_svc, c.span_name AS child_span, c.attr_http_request_method AS child_method, count(*) AS n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.service_name = 'ts-route-plan-service' AND c.attr_http_request_method = 'OPTIONS' GROUP BY ALL ORDER BY n DESC",
          "claim": "1447 OPTIONS requests reached route-plan, all parented by travel-plan's outgoing POST client spans; the method was rewritten in transit."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_request_method, attr_http_response_status_code, count(*) AS c FROM abnormal_traces WHERE service_name = 'ts-travel-plan-service' AND attr_span_kind = 'Server' AND span_name LIKE '%quickest%' GROUP BY ALL",
          "claim": "All 1447 travel-plan /travelPlan/quickest server spans returned HTTP 500 in the abnormal window; none in normal."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) AS c FROM abnormal_logs WHERE service_name = 'ts-travel-plan-service' AND level = 'SEVERE' GROUP BY ALL",
          "claim": "travel-plan logged 1447 SEVERE NullPointerException errors from dispatcherServlet, matching the failing quickest requests."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS c, sum(CASE WHEN attr_status_code = 'Error' THEN 1 ELSE 0 END) AS errs, approx_quantile(duration, 0.95)/1e6 AS p95_ms FROM abnormal_traces WHERE service_name = 'ts-ui-dashboard' AND span_name LIKE '%travelPlan/quickest%' GROUP BY ALL",
          "claim": "ui-dashboard's quickest travel-plan requests: 83 of 100 errored, p95 about 4088 ms, as travel-plan's 500s surface to users."
        }
      ]
    }
  ]
}
```
